return [
  { json: { requestId: 'CR-2026-001', title: 'Update voice routing policy', ownerGroup: 'communications-platform', risk: 'medium', changeWindow: '2026-08-25T22:00:00Z', hasImplementationPlan: true, hasRollbackPlan: true } },
  { json: { requestId: 'CR-2026-002', title: 'Refresh workstation policy', ownerGroup: 'workplace-services', risk: 'low', changeWindow: '2026-08-26T20:00:00Z', hasImplementationPlan: true, hasRollbackPlan: true } },
  { json: { requestId: 'CR-2026-003', title: 'Modify edge routing', ownerGroup: 'communications-platform', risk: 'high', changeWindow: '2026-08-27T23:00:00Z', hasImplementationPlan: true, hasRollbackPlan: false } },
  { json: { requestId: 'CR-2026-004', title: 'Incomplete demonstration request', ownerGroup: 'communications-platform', risk: 'medium', hasImplementationPlan: true, hasRollbackPlan: true } }
];

const required = ['requestId', 'title', 'ownerGroup', 'risk', 'changeWindow', 'hasImplementationPlan', 'hasRollbackPlan'];
const managedGroup = 'communications-platform';
const validRisks = new Set(['low', 'medium', 'high']);

return items.map(({ json: request }) => {
  const missing = required.filter((field) => request[field] === undefined || request[field] === null || request[field] === '');
  if (missing.length || !validRisks.has(request.risk)) {
    return { json: { requestId: request.requestId || 'UNASSIGNED', title: request.title || 'Untitled request', status: 'VALIDATION_ERROR', route: 'ERROR_QUEUE', humanApprovalRequired: true, reasons: missing.length ? [`Missing required fields: ${missing.join(', ')}`] : ['Risk must be low, medium, or high'], checkedAt: new Date().toISOString() } };
  }

  const completePlan = request.hasImplementationPlan && request.hasRollbackPlan;
  if (request.ownerGroup !== managedGroup) {
    return { json: { ...request, status: 'REVIEW_REQUIRED', route: 'EXTERNAL_FAST_TRACK_REVIEW', humanApprovalRequired: true, reasons: ['Request belongs to another operating group; no automatic approval is issued'], checkedAt: new Date().toISOString() } };
  }

  if (!completePlan || request.risk === 'high') {
    const reasons = [];
    if (!request.hasImplementationPlan) reasons.push('Implementation plan is missing');
    if (!request.hasRollbackPlan) reasons.push('Rollback plan is missing');
    if (request.risk === 'high') reasons.push('High-risk change requires explicit review');
    return { json: { ...request, status: 'REVIEW_REQUIRED', route: 'MANAGED_DETAILED_REVIEW', humanApprovalRequired: true, reasons, checkedAt: new Date().toISOString() } };
  }

  return { json: { ...request, status: 'READY_FOR_COMMITTEE', route: 'MANAGED_SUMMARY', humanApprovalRequired: true, reasons: ['Required plans are present; prepared for human committee review'], checkedAt: new Date().toISOString() } };
});
